// Reports the ten most frequent words in a UTF-8 text file.
//
// A word is a maximal run of ASCII letters and digits; every other byte
// separates words. Counting is case-insensitive and output is lower case.
// The file is scanned as raw bytes, so no decoding can alter word boundaries.

const TOP = 10;

function isWordByte(b: number): boolean {
  return (b >= 0x30 && b <= 0x39) || // 0-9
    (b >= 0x41 && b <= 0x5a) || // A-Z
    (b >= 0x61 && b <= 0x7a); // a-z
}

function toLowerByte(b: number): number {
  return b >= 0x41 && b <= 0x5a ? b + 0x20 : b;
}

const path = Deno.args[0];
if (path === undefined) {
  console.error("usage: deno run main.ts <file>");
  Deno.exit(2);
}

const bytes = await Deno.readFile(path);

const counts = new Map<string, number>();
let word: number[] = [];

function flush(): void {
  if (word.length === 0) return;
  const key = String.fromCharCode(...word);
  counts.set(key, (counts.get(key) ?? 0) + 1);
  word = [];
}

for (const b of bytes) {
  if (isWordByte(b)) {
    word.push(toLowerByte(b));
  } else {
    flush();
  }
}
flush();

// Keys are pure ASCII, so default string comparison orders them by byte.
const ranked = [...counts.entries()].sort((a, b) =>
  b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
);

const lines = ranked.slice(0, TOP).map(([w, n]) => `${w} ${n}`);
if (lines.length > 0) {
  console.log(lines.join("\n"));
}

