input.new_string:
const path = Deno.args[0];
if (path === undefined) {
  console.error("usage: deno run main.ts <file>");
  Deno.exit(2);
}

const bytes = await Deno.readFile(path);
const decoder = new TextDecoder("ascii");

const counts = new Map<string, number>();
let start = -1;

// Word bytes are ASCII, so decoding a word and lower-casing it is exact.
function flush(end: number): void {
  if (start < 0) return;
  const key = decoder.decode(bytes.subarray(start, end)).toLowerCase();
  counts.set(key, (counts.get(key) ?? 0) + 1);
  start = -1;
}

for (let i = 0; i < bytes.length; i++) {
  if (isWordByte(bytes[i])) {
    if (start < 0) start = i;
  } else {
    flush(i);
  }
}
flush(bytes.length);

// Keys are pure ASCII, so default string comparison orders them by byte.

